def _build_component_06():
    def rounded(numerator, mode):
        if mode == "floor":
            return numerator // 10000
        return (numerator + 5000) // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            tax = rounded(net * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name])
            choices.append([None] + versions)

        best_vector = None
        best_versions = None
        for values in product(*choices):
            assignment = dict(zip(names, values))
            graph = {name: [] for name in names if assignment[name] is not None}
            valid = True

            for name, version in roots.items():
                selected = assignment.get(name)
                if selected is None or not version[0] <= selected <= version[1]:
                    valid = False
                    break
            if not valid:
                continue

            rows_by_name = {}
            for name in names:
                version = assignment[name]
                if version is None:
                    continue
                if version in blocked.get(name, []):
                    valid = False
                    break
                if name in pins and version != pins[name]:
                    valid = False
                    break
                row = next(row for row in packages[name]
                           if row["version"] == version)
                rows_by_name[name] = row
            if not valid:
                continue

            for name, row in rows_by_name.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_version = assignment.get(dep_name)
                    if (dep_version is None or
                            not dep["min"] <= dep_version <= dep["max"]):
                        valid = False
                        break
                    graph[name].append(dep_name)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            active = set()
            finished = set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                reachable.add(name)
                if any(not visit(child) for child in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            for root in roots:
                if not visit(root):
                    valid = False
                    break
            if not valid or reachable != set(rows_by_name):
                continue

            vector = tuple(-1 if assignment[name] is None else assignment[name]
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assignment[name] for name in names
                                 if assignment[name] is not None}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def feasible(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        for group, bounds in data.get("quotas", {}).items():
            count = counts.get(group, 0)
            if not bounds[0] <= count <= bounds[1]:
                return False

        active_ends = []
        for job in sorted(selected,
                          key=lambda item: (item["start"], item["end"], item["id"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                return False
        return True

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        best_value = None
        best_ids = None
        for selected in _subsets_of_size(jobs, k):
            if not feasible(selected, data):
                continue
            value = sum(job["value"] for job in selected)
            ids = tuple(sorted(job["id"] for job in selected))
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value = value
                best_ids = ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _subsets_of_size(items, size):
    # Generate combinations without requiring any external dependencies.
    if size < 0 or size > len(items):
        return
    indices = list(range(size))
    if size == 0:
        yield []
        return
    while True:
        yield [items[i] for i in indices]
        for position in range(size - 1, -1, -1):
            if indices[position] != position + len(items) - size:
                break
        else:
            return
        indices[position] += 1
        for j in range(position + 1, size):
            indices[j] = indices[j - 1] + 1


